script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "testSuiteCount",
		value: event.payload.model.layoutQuery.count || 0
	}
}

